// Group rows by Project, keep only the latest Date per project.
const rows = $input.all().map(i => i.json);

const groups = {};
for (const row of rows) {
  const project = (row['Project'] || '').trim();
  if (!project) continue;
  const date = new Date(row['Date']);
  if (!groups[project] || date > groups[project].date) {
    groups[project] = {
      date,
      project,
      dateStr: row['Date'],
      whatDid: row['What I did'] || '',
      blocker: row['Blocker/Next step'] || '',
      status: row['Status'] || ''
    };
  }
}

return Object.values(groups).map(g => ({
  json: {
    project: g.project,
    date: g.dateStr,
    whatDid: g.whatDid,
    blocker: g.blocker,
    status: g.status
  }
}));

// Format latest-per-project entries as readable text for the LLM prompt.
const items = $input.all().map(i => i.json);

let text = '';
for (const item of items) {
  text += `## ${item.project}\n`;
  text += `Date: ${item.date}\n`;
  text += `What I did: ${item.whatDid}\n`;
  text += `Blocker / Next step: ${item.blocker}\n`;
  text += `Status: ${item.status}\n\n`;
}

return [{ json: { formattedText: text.trim() } }];
